-- 0416 PROD CHECK, BEFORE the deploy, read-only, ONE statement:
--   npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/slim-laps/before.sql
-- Written by gen.mjs from the migration's hunks. One row, one jsonb column `r`. It reads the catalog, world_config and one small ring table; no large table.
-- BEFORE, wanted: head = the migration before this file's number; applied false; hunks: every `old` 1 and every `new` 0 (prod's bodies are the
--   pre-images: 0409's, and whatever 0410 to 0415 left of these six functions, which is nothing); knobs: npc_route_lap_keep 24,
--   npc_route_lap_keep_hours 26, stats_city_good_keep_days 3, stats_city_good_hour_days 7 (a value the owner has since set is left alone: say so).
--   laps.heap_mb: THE FILL READS THE WHOLE LAP TABLE ONCE. Under about 80 MB (the RUNBOOK's rewrite has run) it takes seconds; at the 226 MB of
--   2026-11-14 with the disk throttled it can take a minute: run scripts/ops/harness/slim-db/RUNBOOK.md step 3b for standing_route_laps first.
-- AFTER, wanted: head = this file's number; applied true; hunks: every `new` 1; trigger true; knobs: npc_route_lap_keep 10,
--   npc_route_lap_keep_hours 0, route_hour_keep_hours 80, npc_invest_lap_hours 8, stats_city_good_keep_days 30, stats_city_good_hour_days 2;
--   book.rows above 0 at once (the fill) and about 900 x 80 = 72,000 after three days; laps.rows falling toward about 12 a merchant route
--   (11,000) over the compactor's next pass of every house (an hour or two).
-- READING after the deploy, at +30 min, +3 h, +24 h: open a merchant's fleet card: "today" and its laps read as before; the Stats tab's merchants
--   (profit a day, laps a day, losing) continuous across the deploy. Then scripts/ops/harness/slim-db/health.sql.
begin transaction read only;
with hk(ord, fn, old, new) as (values
  (1, 'public.route_earnings(uuid)', E'    ''day'',       coalesce((select sum(x.net) from public.standing_route_laps x\n                            where x.route_id = p_route and x.closed_at > now() - interval ''24 hours''), 0),\n    ''day_laps'',  (select count(*) from public.standing_route_laps x\n                   where x.route_id = p_route and x.closed_at > now() - interval ''24 hours''),\n    ''day_since'', (select min(x.closed_at) from public.standing_route_laps x\n                   where x.route_id = p_route and x.closed_at > now() - interval ''24 hours''),\n    ''day_full'',  exists (select 1 from public.standing_route_laps x\n                          where x.route_id = p_route and x.closed_at <= now() - interval ''24 hours''),\n', E'    -- 0416: the day is read by public.route_day (the hour book for the whole hours, the lap rows for the part-hours), so a merchant''s\n    -- lap rows can be her newest ten\n    ''day'',       (select d.net from public.route_day(p_route, now() - interval ''24 hours'', now()) d),\n    ''day_laps'',  (select d.laps from public.route_day(p_route, now() - interval ''24 hours'', now()) d),\n    ''day_since'', (select d.since from public.route_day(p_route, now() - interval ''24 hours'', now()) d),\n    ''day_full'',  public.route_day_full(p_route, now() - interval ''24 hours''),\n'),
  (2, 'world.fleet_trades(uuid)', E'  select jsonb_build_object(\n           ''since'', (select min(w.closed_at) from w),\n           ''full'', exists (select 1 from public.standing_route_laps y\n                            where y.route_id = sr.id and y.closed_at <= now() - interval ''24 hours''),\n           ''laps'', (select count(*) from w),\n           ''laps_traded'', (select count(*) from w where w.trades is not null),\n           ''sold'', coalesce((select sum(w.sold) from w), 0),\n           ''bought'', coalesce((select sum(w.bought) from w), 0),\n           ''supplies'', coalesce((select sum(w.supplies) from w), 0),\n           ''repairs'', coalesce((select sum(w.repairs) from w), 0),\n           ''wages'', coalesce((select sum(w.wages) from w), 0),\n           ''taxes'', coalesce((select sum(w.taxes) from w), 0),   -- 0122\n           ''stock_in'', coalesce((select sum(w.stock_in) from w), 0),\n           ''stock_out'', coalesce((select sum(w.stock_out) from w), 0),\n           ''net'', coalesce((select sum(w.net) from w), 0),\n', E'  -- 0416: the day''s totals are public.route_day''s (the hour book and the part-hours'' lap rows: the figures route_earnings prints); the laps\n  -- that still carry their trades, and the goods below, are read from the lap rows as before\n  select (select jsonb_build_object(\n           ''since'', d.since,\n           ''full'', public.route_day_full(sr.id, now() - interval ''24 hours''),\n           ''laps'', d.laps,\n           ''laps_traded'', (select count(*) from w where w.trades is not null),\n           ''sold'', d.sold,\n           ''bought'', d.bought,\n           ''supplies'', d.supplies,\n           ''repairs'', d.repairs,\n           ''wages'', d.wages,\n           ''taxes'', d.taxes,   -- 0122\n           ''stock_in'', d.stock_in,\n           ''stock_out'', d.stock_out,\n           ''net'', d.net)\n            from public.route_day(sr.id, now() - interval ''24 hours'', now()) d)\n         || jsonb_build_object(\n'),
  (3, 'public.stats_merchants_window(timestamp with time zone,timestamp with time zone)', E'    select l.route_id, l.net\n      from public.standing_route_laps l\n     where l.closed_at > p_from and l.closed_at <= p_to and l.lap_no >= 2\n  ), h as (\n    select p.company_name as name, n.code as nation, sum(l.net)::bigint as day, count(*)::int as laps\n', E'    -- 0416: the whole hours of the window from public.route_hour_laps (laps 2 onwards: net2, laps2, neg2), its two part-hours from the lap\n    -- rows still kept (a merchant keeps her newest ten). The tab''s "minutes since the count" lies inside one or two part-hours: exact.\n    select b.route_id, b.net2 as net, b.laps2 as n, b.neg2 as neg\n      from public.route_hour_laps b\n     where b.hour >= date_trunc(''hour'', p_from) + case when p_from > date_trunc(''hour'', p_from) then interval ''1 hour'' else interval ''0'' end\n       and b.hour < date_trunc(''hour'', p_to) and b.laps2 > 0\n    union all\n    select l.route_id, l.net, 1, (l.net <= 0)::int\n      from public.standing_route_laps l\n     where l.closed_at > p_from and l.closed_at <= p_to and l.lap_no >= 2\n       and (l.closed_at < date_trunc(''hour'', p_from) + case when p_from > date_trunc(''hour'', p_from) then interval ''1 hour'' else interval ''0'' end\n            or l.closed_at >= date_trunc(''hour'', p_to))\n  ), h as (\n    select p.company_name as name, n.code as nation, sum(l.net)::bigint as day, sum(l.n)::int as laps\n'),
  (4, 'public.stats_merchants_window(timestamp with time zone,timestamp with time zone)', E'           ''n'', (select count(*) from l),\n           ''neg'', (select count(*) from l where l.net <= 0),\n', E'           ''n'', coalesce((select sum(l.n) from l), 0),\n           ''neg'', coalesce((select sum(l.neg) from l), 0),\n'),
  (5, 'public.npc_share_budget(timestamp with time zone,uuid,bigint)', E'            cross join lateral (select x.bought + x.supplies + x.repairs + x.wages + x.taxes + x.insurance as spend\n                                  from public.standing_route_laps x\n                                 where x.route_id = nf.route_id and x.closed_at > p_now - interval ''3 days''\n                                 order by x.lap_no desc limit 20) l\n', E'            -- 0416: the dearest lap of the last npc_invest_lap_hours, from the hour book (it read her newest 20 lap rows; she keeps ten)\n            cross join lateral (select b.spend_max as spend\n                                  from public.route_hour_laps b\n                                 where b.route_id = nf.route_id\n                                   and b.hour >= date_trunc(''hour'', p_now - make_interval(hours => greatest(public.wc_int(''npc_invest_lap_hours''), 1)))) l\n'),
  (6, 'public.npc_compact_houses(uuid[],timestamp with time zone)', E'                and l.closed_at < p_now - make_interval(hours => greatest(public.wc_int(''npc_route_lap_keep_hours''), 25))\n                and l.lap_no <= sr.lap_no - greatest(public.wc_int(''npc_route_lap_keep''), 20)\n', E'                -- 0416: her newest npc_route_lap_keep alone (never under 10); the hours'' window only while its knob is above 0. The day\n                -- figures no longer read these rows (public.route_hour_laps).\n                and (public.wc_int(''npc_route_lap_keep_hours'') <= 0\n                     or l.closed_at < p_now - make_interval(hours => public.wc_int(''npc_route_lap_keep_hours'')))\n                and l.lap_no <= sr.lap_no - greatest(public.wc_int(''npc_route_lap_keep''), 10)\n'),
  (7, 'public.tick_compact(boolean,boolean)', E'    if p_commit then commit; end if;\n  end if;\n  insert into public.compact_runs (slot, at, ms, receipt)\n', E'    if p_commit then commit; end if;\n  end if;\n  -- 0416: THE HOUR BOOK''S OLD HOURS (public.route_hour_laps past route_hour_keep_hours, never under 30), compact_trim_rows a run.\n  begin\n    delete from public.route_hour_laps b\n     where b.ctid = any(array(select x.ctid from public.route_hour_laps x\n                               where x.hour < v_now - make_interval(hours => greatest(public.wc_int(''route_hour_keep_hours''), 30))\n                               order by x.hour\n                               limit greatest(public.wc_int(''compact_trim_rows''), 1)));\n  exception when others then\n    v_fail := v_fail + 1;\n    v_note := coalesce(v_note, ''hour book: '' || sqlerrm);\n  end;\n  if p_commit then commit; end if;\n  insert into public.compact_runs (slot, at, ms, receipt)\n')
), body as (
  select hk.ord, hk.fn, hk.old, hk.new, replace(pg_get_functiondef(hk.fn::regprocedure), E'\r', '') as def from hk
)
select jsonb_build_object(
  'head', (select max(version) from supabase_migrations.schema_migrations),
  'applied', to_regclass('public.route_hour_laps') is not null,
  'hunks', (select jsonb_agg(jsonb_build_object('ord', b.ord, 'fn', b.fn,
                     'old', (length(b.def) - length(replace(b.def, b.old, ''))) / length(b.old),
                     'new', (length(b.def) - length(replace(b.def, b.new, ''))) / length(b.new)) order by b.ord) from body b),
  'trigger', exists (select 1 from pg_trigger t where t.tgrelid = 'public.standing_route_laps'::regclass and t.tgname = 'standing_route_laps_hour_book'),
  'knobs', (select jsonb_object_agg(c.key, c.value) from public.world_config c
             where c.key in ('npc_route_lap_keep', 'npc_route_lap_keep_hours', 'route_hour_keep_hours', 'npc_invest_lap_hours', 'stats_city_good_keep_days',
                             'stats_city_good_hour_days', 'stats_city_good_fine_hours', 'standing_route_lap_keep', 'compact_trim_rows')),
  'laps', (select jsonb_build_object('rows', c.reltuples::bigint, 'heap_mb', pg_relation_size(c.oid) / 1048576, 'total_mb', pg_total_relation_size(c.oid) / 1048576)
             from pg_class c where c.oid = 'public.standing_route_laps'::regclass),
  'book', (select jsonb_build_object('rows', c.reltuples::bigint, 'total_mb', pg_total_relation_size(c.oid) / 1048576)
             from pg_class c where c.oid = to_regclass('public.route_hour_laps')),
  'compact', (select jsonb_agg(jsonb_build_object('at', c.at, 'ms', c.ms, 'houses', c.receipt->'houses', 'left', c.receipt->'left',
                                                  'failed', c.receipt->'failed', 'note', c.receipt->'note') order by c.at desc)
                from (select * from public.compact_runs order by at desc limit 3) c)
) as r;
commit;
